<?php

declare(strict_types=1);
require_once __DIR__.'/CompanyCredits.php';require_once __DIR__.'/CompanyExpenseSchema.php';require_once __DIR__.'/CompanyCurrencyUnits.php';require_once __DIR__.'/CompanyInvoiceBalance.php';

/** Current financial position, never a global report with a post-hoc company filter. */
final class CompanyReports
{
    private IssuerResourceAccess $acl;
    public const CAPABILITIES=[['reports','view'],['invoices','view'],['payments','view'],['credit_notes','view'],['expenses','view']];
    public function __construct(private $db,private string $p,private $guard=null,private array $guardTables=[]){if(!preg_match('/^[A-Za-z0-9_]+$/D',$p))throw new InvalidArgumentException('Invalid table prefix');$this->acl=new IssuerResourceAccess($db,$p);}
    private function rows(string $sql,array $args=[]):array{return IssuerStorage::query($this->db,$sql,$args)->result_array();}
    private function authorize(int $issuer,int $actor):void{foreach(self::CAPABILITIES as [$feature,$cap])if(!$this->acl->can($issuer,$actor,$feature,$cap))throw new DomainException('company_report_access_denied');}
    private function transaction(int $issuer,int $actor,callable $work)
    {
        $this->authorize($issuer,$actor);CompanyCreditSchema::assertValid($this->db,$this->p);CompanyExpenseSchema::assertValid($this->db,$this->p);
        $balanceTables=(new CompanyInvoiceBalance($this->db,$this->p))->tables();return IssuerTransaction::run($this->db,$this->p,array_values(array_unique(array_merge(['issuers_lock','issuers_registry','issuers_installation_identity','issuers_staff','issuers_resource_permissions','staff','creditnotes','credits','creditnote_refunds','invoices','issuers_invoice_documents','company_credit_documents','company_credit_entries','currencies','company_currency_units','invoicepaymentrecords','company_payment_receipts','company_expenses','company_expense_categories','issuers_audit'],$this->guardTables,$balanceTables))),function()use($issuer,$actor,$work){$this->acl->lockFinancialIdentity($issuer,$actor);$this->authorize($issuer,$actor);if($this->guard!==null)($this->guard)();$result=$work();$this->authorize($issuer,$actor);if($this->guard!==null)($this->guard)();return $result;});
    }
    private static function amount($value):int{try{$amount=CompanyInvoiceAmounts::minor((string)$value);if($amount>CompanyInvoiceAmounts::MAX)throw new DomainException();return $amount;}catch(Throwable $e){throw new DomainException('company_report_balance_review');}}
    private static function sum(int &$target,int $amount):void{if($amount<0||$amount>PHP_INT_MAX-$target)throw new DomainException('company_report_balance_review');$target+=$amount;}
    private static function zero(string $currency):array{return ['currency'=>$currency,'invoiced'=>0,'received'=>0,'received_original'=>0,'received_reversed'=>0,'received_manual_reversed'=>0,'received_external_reversed'=>0,'applied_credit'=>0,'receivable'=>0,'settlement_discount'=>0,'settlement_abatement'=>0,'noncash_reductions'=>0,'settlement_discount_original'=>0,'settlement_abatement_original'=>0,'settlement_discount_reversed'=>0,'settlement_abatement_reversed'=>0,'component_observations'=>['receipt_count'=>0,'principal_received'=>0,'charges_aggregate'=>0,'paid'=>0,'net'=>0,'tariff_deducted_observed'=>0,'net_known_count'=>0,'net_unknown_count'=>0,'basis'=>'only_immutable_component_receipts_not_all_bank_movements','declared_reversals'=>self::observationZero(),'active'=>self::observationZero()],'credit_issued'=>0,'credit_available'=>0,'credit_refunded'=>0,'expenses'=>0,'expense_tax'=>0,'invoice_count'=>0,'credit_count'=>0,'expense_count'=>0];}
    private static function observationZero():array{return ['receipt_count'=>0,'principal_received'=>0,'charges_aggregate'=>0,'paid'=>0,'net'=>0,'tariff_deducted_observed'=>0,'net_known_count'=>0,'net_unknown_count'=>0];}
    private static function addObservation(array &$target,array $component):void
    {
        $target['receipt_count']++;if(($component['basis']??null)===CompanyBankComponentsData::TARIFF_BASIS)self::sum($target['tariff_deducted_observed'],self::amount($component['fees']));foreach(['principal_received'=>'cash_principal','charges_aggregate'=>'charges_aggregate','paid'=>'paid'] as $field=>$source)self::sum($target[$field],self::amount($component[$source]));if($component['net_observed']===null)$target['net_unknown_count']++;else{$target['net_known_count']++;self::sum($target['net'],self::amount($component['net_observed']));}
    }
    private static function finishObservation(array &$target):void
    {
        foreach(['principal_received','charges_aggregate','paid','net','tariff_deducted_observed'] as $field)$target[$field]=$target['receipt_count']===0||($field==='net'&&$target['net_unknown_count']>0)?null:CompanyInvoiceAmounts::decimal($target[$field]);
    }
    private function financial(int $issuer,int $actor):array
    {
        $totals=[];$creditDocs=[];$reader=new CompanyCredits($this->db,$this->p);$counts=['cancelled_invoices'=>0,'cancelled_credits'=>0,'cancelled_expenses'=>0];
        $currency=function(string $name)use(&$totals):string{if(!preg_match('/^[A-Z]{3}$/D',$name))throw new DomainException('company_report_balance_review');if(!isset($totals[$name]))$totals[$name]=self::zero($name);return $name;};
        foreach($this->rows('SELECT c.id,d.credit_id snapshot_id FROM '.$this->p.'creditnotes c LEFT JOIN '.$this->p.'company_credit_documents d ON d.credit_id=c.id AND d.issuer_id=c.issuer_id WHERE c.issuer_id=? ORDER BY c.id FOR UPDATE',[$issuer]) as $row){if($row['snapshot_id']===null)throw new DomainException('company_report_balance_review');$doc=$reader->inOwnedTransaction($issuer,$actor,$row['id']);$creditDocs[$doc['id']]=$doc;if($doc['status']===3){$counts['cancelled_credits']++;continue;}$name=$currency($doc['currency']);$totals[$name]['credit_count']++;foreach(['credit_issued'=>$doc['amounts']['total'],'credit_available'=>$doc['available'],'credit_refunded'=>$doc['refunded']] as $field=>$value)self::sum($totals[$name][$field],self::amount($value));}
        $balanceReader=new CompanyInvoiceBalance($this->db,$this->p);
        foreach($this->rows('SELECT i.id,i.currency,i.status,d.invoice_id snapshot_id FROM '.$this->p.'invoices i LEFT JOIN '.$this->p.'issuers_invoice_documents d ON d.invoice_id=i.id AND d.issuer_id=i.issuer_id WHERE i.issuer_id=? ORDER BY i.id FOR UPDATE',[$issuer]) as $invoice){
            if($invoice['snapshot_id']===null)throw new DomainException('company_report_balance_review');try{$position=$balanceReader->inOwned($issuer,$actor,$invoice['id']);}catch(DomainException $e){throw new DomainException('company_report_balance_review');}if(self::amount($position['total'])<1)throw new DomainException('company_report_balance_review');$unit=(new CompanyCurrencyUnits($this->db,$this->p))->resolveRead($invoice['currency']);$status=(int)$invoice['status'];if($status===5){$counts['cancelled_invoices']++;continue;}if($status===6)continue;
            $name=$currency($unit['iso_code']);$totals[$name]['invoice_count']++;foreach(['invoiced'=>'total','received'=>'received','received_original'=>'received_original','received_reversed'=>'received_reversed','received_manual_reversed'=>'received_manual_reversed','received_external_reversed'=>'received_external_reversed','applied_credit'=>'applied_credit','receivable'=>'receivable','settlement_discount'=>'settlement_discount','settlement_abatement'=>'settlement_abatement','noncash_reductions'=>'noncash_reductions','settlement_discount_original'=>'settlement_discount_original','settlement_abatement_original'=>'settlement_abatement_original','settlement_discount_reversed'=>'settlement_discount_reversed','settlement_abatement_reversed'=>'settlement_abatement_reversed'] as $field=>$source)self::sum($totals[$name][$field],self::amount($position[$source]));
            foreach($position['components'] as $paymentId=>$component){$observation=&$totals[$name]['component_observations'];self::addObservation($observation,$component);$group=isset($position['reversals'][$paymentId])?'declared_reversals':'active';self::addObservation($observation[$group],$component);unset($observation);}
        }
        foreach($this->rows('SELECT e.currency,e.amount_cents,e.tax_cents,e.tax_rate,e.total_cents,e.state,c.issuer_id category_issuer FROM '.$this->p.'company_expenses e JOIN '.$this->p.'company_expense_categories c ON c.id=e.category_id WHERE e.issuer_id=? ORDER BY e.id FOR UPDATE',[$issuer]) as $expense){if((int)$expense['category_issuer']!==$issuer||!in_array($expense['state'],['recorded','cancelled'],true))throw new DomainException('company_report_balance_review');$base=(int)$expense['amount_cents'];$tax=(int)$expense['tax_cents'];$rate=(int)$expense['tax_rate'];$total=(int)$expense['total_cents'];if($base<1||$base>99999999999||$rate<0||$rate>10000||$tax!==intdiv($base*$rate+5000,10000)||$total!==$base+$tax)throw new DomainException('company_report_balance_review');if($expense['state']==='cancelled'){$counts['cancelled_expenses']++;continue;}$name=$currency($expense['currency']);$totals[$name]['expense_count']++;self::sum($totals[$name]['expenses'],$total);self::sum($totals[$name]['expense_tax'],$tax);}
        ksort($totals);foreach($totals as &$row)foreach(['invoiced','received','received_original','received_reversed','received_manual_reversed','received_external_reversed','settlement_discount_original','settlement_abatement_original','settlement_discount_reversed','settlement_abatement_reversed','applied_credit','receivable','credit_issued','credit_available','credit_refunded','expenses','expense_tax','settlement_discount','settlement_abatement','noncash_reductions'] as $field)$row[$field]=CompanyInvoiceAmounts::decimal($row[$field]);unset($row);foreach($totals as &$row){$observation=&$row['component_observations'];self::finishObservation($observation);self::finishObservation($observation['declared_reversals']);self::finishObservation($observation['active']);unset($observation);}unset($row);return ['issuer_id'=>$issuer,'generated_at'=>date('Y-m-d H:i:s'),'basis'=>'current_position_verified_cash_and_noncash_separated','currencies'=>array_values($totals),'counts'=>$counts];
    }
    public function financialPosition($issuer,$actor):array{$issuer=IssuerPolicy::id($issuer);$actor=IssuerPolicy::id($actor);return $this->transaction($issuer,$actor,fn():array=>$this->financial($issuer,$actor));}
    public function csv($issuer,$actor):string
    {
        $issuer=IssuerPolicy::id($issuer);$actor=IssuerPolicy::id($actor);return $this->transaction($issuer,$actor,function()use($issuer,$actor):string{$report=$this->financial($issuer,$actor);$stream=fopen('php://temp','w+');if(!$stream)throw new RuntimeException('issuer_report_export_failed');try{fwrite($stream,"\xEF\xBB\xBF");fputcsv($stream,['Empresa','Gerado em','Moeda','Faturas emitidas','Recebimentos nominais após estornos','Crédito aplicado','A receber','Créditos emitidos','Crédito disponível','Reembolsos líquidos registrados','Despesas registradas','Tributos de despesas','Qtd. faturas','Qtd. créditos','Qtd. despesas','Desconto sem caixa','Abatimento sem caixa','Extinções sem caixa','Qtd. recibos com componentes','Principal observado nos componentes','Encargos agregados observados não fiscais','Pago observado nos componentes','Líquido observado nos componentes','Qtd. líquidos conhecidos','Qtd. líquidos desconhecidos','Cobertura dos componentes','Principal nominal original','Principal revertido total','Principal revertido manualmente','Principal revertido por estorno externo declarado','Desconto sem caixa original','Abatimento sem caixa original','Desconto sem caixa revertido','Abatimento sem caixa revertido','Reversão externa declarada: Qtd. recibos','Reversão externa declarada: Principal','Reversão externa declarada: Encargos agregados não fiscais','Reversão externa declarada: Pago observado','Reversão externa declarada: Líquido observado','Reversão externa declarada: Qtd. líquidos conhecidos','Reversão externa declarada: Qtd. líquidos desconhecidos','Composição ativa após reversões declaradas: Qtd. recibos','Composição ativa após reversões declaradas: Principal','Composição ativa após reversões declaradas: Encargos agregados não fiscais','Composição ativa após reversões declaradas: Pago observado','Composição ativa após reversões declaradas: Líquido observado','Composição ativa após reversões declaradas: Qtd. líquidos conhecidos','Composição ativa após reversões declaradas: Qtd. líquidos desconhecidos','Tarifa bancária deduzida observada sem despesa fiscal automática'],';', '"', '');foreach($report['currencies'] as $row)fputcsv($stream,[$issuer,$report['generated_at'],$row['currency'],$row['invoiced'],$row['received'],$row['applied_credit'],$row['receivable'],$row['credit_issued'],$row['credit_available'],$row['credit_refunded'],$row['expenses'],$row['expense_tax'],$row['invoice_count'],$row['credit_count'],$row['expense_count'],$row['settlement_discount'],$row['settlement_abatement'],$row['noncash_reductions'],$row['component_observations']['receipt_count'],$row['component_observations']['principal_received'],$row['component_observations']['charges_aggregate'],$row['component_observations']['paid'],$row['component_observations']['net'],$row['component_observations']['net_known_count'],$row['component_observations']['net_unknown_count'],$row['component_observations']['basis'],$row['received_original'],$row['received_reversed'],$row['received_manual_reversed'],$row['received_external_reversed'],$row['settlement_discount_original'],$row['settlement_abatement_original'],$row['settlement_discount_reversed'],$row['settlement_abatement_reversed'],$row['component_observations']['declared_reversals']['receipt_count'],$row['component_observations']['declared_reversals']['principal_received'],$row['component_observations']['declared_reversals']['charges_aggregate'],$row['component_observations']['declared_reversals']['paid'],$row['component_observations']['declared_reversals']['net'],$row['component_observations']['declared_reversals']['net_known_count'],$row['component_observations']['declared_reversals']['net_unknown_count'],$row['component_observations']['active']['receipt_count'],$row['component_observations']['active']['principal_received'],$row['component_observations']['active']['charges_aggregate'],$row['component_observations']['active']['paid'],$row['component_observations']['active']['net'],$row['component_observati